  "pr.flat": { en: "flat", es: "fijo", zh: "统一价", yue: "統一價", ru: "фикс.", fr: "forfait", bn: "নির্দিষ্ট", ko: "정액", ht: "fiks", it: "fisso", ar: "ثابت", pl: "stała" },
