  "ct.step1": { en: "You send the brief", es: "Envías el brief", zh: "你发送需求简报", yue: "你發送需求簡報", ru: "Вы отправляете бриф", fr: "Vous envoyez le brief", bn: "আপনি ব্রিফ পাঠান", ko: "브리프를 보냅니다", ht: "Ou voye rezime a", it: "Ci invii il brief", ar: "ترسل الملخّص", pl: "Wysyłasz brief" },
  "ct.step2": { en: "We review your project", es: "Revisamos tu proyecto", zh: "我们审阅你的项目", yue: "我哋審閱你嘅項目", ru: "Мы изучаем ваш проект", fr: "On étudie votre projet", bn: "আমরা আপনার প্রকল্প পর্যালোচনা করি", ko: "프로젝트를 검토합니다", ht: "Nou revize pwojè ou", it: "Esaminiamo il tuo progetto", ar: "نراجع مشروعك", pl: "Analizujemy twój projekt" },
  "ct.step3": { en: "Free 30-min strategy call", es: "Llamada de estrategia gratuita de 30 min", zh: "免费 30 分钟策略通话", yue: "免費 30 分鐘策略通話", ru: "Бесплатный 30-минутный стратегический звонок", fr: "Appel stratégie gratuit de 30 min", bn: "বিনামূল্যে ৩০ মিনিটের কৌশল কল", ko: "무료 30분 전략 통화", ht: "Apèl estrateji gratis 30 minit", it: "Chiamata strategica gratuita di 30 min", ar: "مكالمة استراتيجية مجانية 30 دقيقة", pl: "Bezpłatna 30-min rozmowa strategiczna" },
  "ct.step4": { en: "Proposal within 24 hours", es: "Propuesta en 24 horas", zh: "24 小时内提交方案", yue: "24 小時內提交方案", ru: "Предложение в течение 24 часов", fr: "Proposition sous 24 heures", bn: "২৪ ঘণ্টার মধ্যে প্রস্তাব", ko: "24시간 내 제안서", ht: "Pwopozisyon nan 24 èdtan", it: "Proposta entro 24 ore", ar: "عرض خلال 24 ساعة", pl: "Oferta w ciągu 24 godzin" },
  "ct.sent.h": { en: "Brief received.", es: "Brief recibido.", zh: "已收到需求简报。", yue: "已收到需求簡報。", ru: "Бриф получен.", fr: "Brief bien reçu.", bn: "ব্রিফ পেয়েছি।", ko: "브리프를 받았습니다.", ht: "Nou resevwa rezime a.", it: "Brief ricevuto.", ar: "تمّ استلام الملخّص.", pl: "Brief odebrany." },
  "ct.sent.p": { en: "We'll be in touch within 24 hours. Keep an eye on your inbox.", es: "Nos pondremos en contacto en 24 horas. Revisa tu bandeja de entrada.", zh: "我们会在 24 小时内联系你。请留意你的邮箱。", yue: "我哋會喺 24 小時內聯絡你。請留意你嘅郵箱。", ru: "Мы свяжемся в течение 24 часов. Следите за почтой.", fr: "On vous recontacte sous 24 heures. Gardez un œil sur votre boîte mail.", bn: "আমরা ২৪ ঘণ্টার মধ্যে যোগাযোগ করব। আপনার ইনবক্সে চোখ রাখুন।", ko: "24시간 내에 연락드리겠습니다. 받은 편지함을 확인해 주세요.", ht: "Nou pral kontakte ou nan 24 èdtan. Veye bwat resepsyon ou.", it: "Ti contatteremo entro 24 ore. Tieni d'occhio la casella di posta.", ar: "سنتواصل معك خلال 24 ساعة. تابع بريدك الوارد.", pl: "Odezwiemy się w ciągu 24 godzin. Miej oko na skrzynkę." },
  "ct.f.name": { en: "Name", es: "Nombre", zh: "姓名", yue: "姓名", ru: "Имя", fr: "Nom", bn: "নাম", ko: "이름", ht: "Non", it: "Nome", ar: "الاسم", pl: "Imię" },
  "ct.f.namePh": { en: "Your name", es: "Tu nombre", zh: "你的姓名", yue: "你嘅姓名", ru: "Ваше имя", fr: "Votre nom", bn: "আপনার নাম", ko: "이름", ht: "Non ou", it: "Il tuo nome", ar: "اسمك", pl: "Twoje imię" },
  "ct.f.email": { en: "Email", es: "Correo", zh: "邮箱", yue: "電郵", ru: "Эл. почта", fr: "E-mail", bn: "ইমেইল", ko: "이메일", ht: "Imèl", it: "Email", ar: "البريد الإلكتروني", pl: "E-mail" },
  "ct.f.business": { en: "Business", es: "Negocio", zh: "企业", yue: "企業", ru: "Компания", fr: "Entreprise", bn: "ব্যবসা", ko: "비즈니스", ht: "Biznis", it: "Attività", ar: "النشاط التجاري", pl: "Firma" },
