  "ct.f.budget": { en: "Budget", es: "Presupuesto", zh: "预算", yue: "預算", ru: "Бюджет", fr: "Budget", bn: "বাজেট", ko: "예산", ht: "Bidjè", it: "Budget", ar: "الميزانية", pl: "Budżet" },
  "ct.f.budgetPh": { en: "Select a range", es: "Selecciona un rango", zh: "选择一个区间", yue: "揀一個範圍", ru: "Выберите диапазон", fr: "Choisissez une fourchette", bn: "একটি পরিসর নির্বাচন করুন", ko: "범위 선택", ht: "Chwazi yon ranje", it: "Seleziona un intervallo", ar: "اختر نطاقًا", pl: "Wybierz zakres" },
  "ct.f.custom": { en: "Custom / Enterprise", es: "Personalizado / Empresa", zh: "定制 / 企业", yue: "訂製 / 企業", ru: "Индивидуально / Бизнес", fr: "Sur mesure / Grand compte", bn: "কাস্টম / এন্টারপ্রাইজ", ko: "맞춤 / 기업", ht: "Sou mezi / Antrepriz", it: "Su misura / Enterprise", ar: "مخصص / مؤسسات", pl: "Na miarę / Enterprise" },
  "ct.f.details": { en: "Project details", es: "Detalles del proyecto", zh: "项目详情", yue: "項目詳情", ru: "Детали проекта", fr: "Détails du projet", bn: "প্রকল্পের বিবরণ", ko: "프로젝트 상세", ht: "Detay pwojè", it: "Dettagli del progetto", ar: "تفاصيل المشروع", pl: "Szczegóły projektu" },
  "ct.f.detailsPh": { en: "What do you need? What's working, what isn't? Who's your customer?", es: "¿Qué necesitas? ¿Qué funciona y qué no? ¿Quién es tu cliente?", zh: "你需要什么？什么有效，什么无效？你的客户是谁？", yue: "你需要啲乜？乜嘢有效，乜嘢冇效？你嘅客戶係邊個？", ru: "Что вам нужно? Что работает, а что нет? Кто ваш клиент?", fr: "De quoi avez-vous besoin ? Qu'est-ce qui marche, qu'est-ce qui ne marche pas ? Qui est votre client ?", bn: "আপনার কী দরকার? কী কাজ করছে, কী করছে না? আপনার গ্রাহক কে?", ko: "무엇이 필요하세요? 무엇이 잘되고 무엇이 안 되나요? 고객은 누구인가요?", ht: "Kisa ou bezwen? Kisa k ap mache, kisa ki pa mache? Kiyès ki kliyan ou?", it: "Di cosa hai bisogno? Cosa funziona e cosa no? Chi è il tuo cliente?", ar: "ماذا تحتاج؟ ما الذي ينجح وما الذي لا ينجح؟ من هو عميلك؟", pl: "Czego potrzebujesz? Co działa, a co nie? Kto jest twoim klientem?" },
