  "pl.ef.dedicated": { en: "Dedicated account manager", es: "Gerente de cuenta dedicado", zh: "专属客户经理", yue: "專屬客戶經理", ru: "Персональный менеджер", fr: "Chargé de compte dédié", bn: "নিবেদিত অ্যাকাউন্ট ম্যানেজার", ko: "전담 어카운트 매니저", ht: "Manadjè kont dedye", it: "Account manager dedicato", ar: "مدير حساب مخصّص", pl: "Dedykowany opiekun klienta" },
