  "nf.h1": { en: "This box is empty.", es: "Esta caja está vacía.", zh: "这个盒子是空的。", yue: "呢個盒係空嘅。", ru: "Эта коробка пуста.", fr: "Cette boîte est vide.", bn: "এই বাক্সটি খালি।", ko: "이 상자는 비어 있습니다.", ht: "Bwat sa a vid.", it: "Questa scatola è vuota.", ar: "هذا الصندوق فارغ.", pl: "To pudełko jest puste." },
  "nf.sub": { en: "The page you're looking for got lost in shipping. Let's get you back to something real.", es: "La página que buscas se perdió en el envío. Volvamos a algo real.", zh: "你要找的页面在运送途中弄丢了。我们带你回到实实在在的内容。", yue: "你搵緊嘅頁面喺運送途中唔見咗。等我哋帶你返去啲實在嘅嘢。", ru: "Страница, которую вы ищете, потерялась при доставке. Давайте вернём вас к чему-то реальному.", fr: "La page que vous cherchez s'est perdue en chemin. Ramenons-vous vers quelque chose de réel.", bn: "আপনি যে পৃষ্ঠাটি খুঁজছেন তা শিপিংয়ে হারিয়ে গেছে। চলুন আপনাকে সত্যিকারের কিছুতে ফিরিয়ে নিই।", ko: "찾으시는 페이지가 배송 중 분실됐습니다. 실제 있는 곳으로 다시 안내해 드릴게요.", ht: "Paj w ap chèche a pèdi nan livrezon. Ann mennen w tounen nan yon bagay reyèl.", it: "La pagina che cerchi si è persa durante la spedizione. Torniamo a qualcosa di reale.", ar: "الصفحة التي تبحث عنها ضاعت أثناء الشحن. لنعدك إلى شيء حقيقي.", pl: "Strona, której szukasz, zgubiła się w transporcie. Wróćmy do czegoś prawdziwego." },
  "nf.home": { en: "Back home", es: "Volver al inicio", zh: "返回首页", yue: "返回首頁", ru: "На главную", fr: "Retour à l'accueil", bn: "হোমে ফিরুন", ko: "홈으로", ht: "Tounen lakay", it: "Torna alla home", ar: "العودة للرئيسية", pl: "Wróć na stronę główną" },
