  "an.m5.sub": { en: "average across clients", es: "promedio entre clientes", zh: "客户平均值", yue: "客戶平均值", ru: "в среднем по клиентам", fr: "moyenne chez les clients", bn: "ক্লায়েন্টদের গড়", ko: "고객 평균", ht: "mwayèn atravè kliyan yo", it: "media tra i clienti", ar: "المتوسط عبر العملاء", pl: "średnio wśród klientów" },
  "an.m6.label": { en: "Sites monitored", es: "Sitios monitoreados", zh: "监控的网站", yue: "監控嘅網站", ru: "Сайтов под мониторингом", fr: "Sites surveillés", bn: "পর্যবেক্ষিত সাইট", ko: "모니터링 사이트", ht: "Sit ki siveye", it: "Siti monitorati", ar: "مواقع مراقَبة", pl: "Monitorowane strony" },
  "an.m6.sub": { en: "real-time dashboards", es: "paneles en tiempo real", zh: "实时仪表盘", yue: "即時儀表板", ru: "дашборды в реальном времени", fr: "tableaux de bord en temps réel", bn: "রিয়েল-টাইম ড্যাশবোর্ড", ko: "실시간 대시보드", ht: "tablo debò an tan reyèl", it: "dashboard in tempo reale", ar: "لوحات معلومات فورية", pl: "pulpity w czasie rzeczywistym" },
  "an.dashLook": { en: "A look inside the dashboard", es: "Un vistazo al panel", zh: "仪表盘一览", yue: "儀表板一覽", ru: "Взгляд внутрь дашборда", fr: "Un aperçu du tableau de bord", bn: "ড্যাশবোর্ডের ভেতরে এক ঝলক", ko: "대시보드 들여다보기", ht: "Yon gade anndan tablo debò a", it: "Uno sguardo dentro la dashboard", ar: "نظرة داخل لوحة المعلومات", pl: "Zajrzyj do pulpitu" },
