  "an.weekly": { en: "Weekly", es: "Semanal", zh: "每周", yue: "每週", ru: "Неделя", fr: "Hebdomadaire", bn: "সাপ্তাহিক", ko: "주간", ht: "Chak semèn", it: "Settimanale", ar: "أسبوعي", pl: "Tygodniowo" },
  "an.monthly": { en: "Monthly", es: "Mensual", zh: "每月", yue: "每月", ru: "Месяц", fr: "Mensuel", bn: "মাসিক", ko: "월간", ht: "Chak mwa", it: "Mensile", ar: "شهري", pl: "Miesięcznie" },
