  "pv.noIndustry": { en: "Don't see your industry?", es: "¿No ves tu sector?", zh: "没看到你的行业？", yue: "睇唔到你嘅行業？", ru: "Не видите свою отрасль?", fr: "Votre secteur n'y est pas ?", bn: "আপনার শিল্প দেখছেন না?", ko: "당신의 업종이 없나요?", ht: "Ou pa wè endistri ou?", it: "Non trovi il tuo settore?", ar: "لا ترى قطاعك؟", pl: "Nie widzisz swojej branży?" },
  "pv.noIndustry.d": { en: "We'll build a custom preview for your business, free, no strings attached.", es: "Crearemos una vista previa a medida para tu negocio, gratis, sin compromiso.", zh: "我们会为你的生意免费打造一份定制预览，绝无附加条件。", yue: "我哋會為你盤生意免費打造一份訂製預覽，絕無附加條件。", ru: "Мы бесплатно сделаем индивидуальное превью для вашего бизнеса, без обязательств.", fr: "On construira un aperçu sur mesure pour votre entreprise, gratuitement, sans engagement.", bn: "আমরা আপনার ব্যবসার জন্য একটি কাস্টম প্রিভিউ বানাব, বিনামূল্যে, কোনো শর্ত ছাড়াই।", ko: "당신의 비즈니스를 위한 맞춤 미리보기를 무료로, 조건 없이 만들어 드립니다.", ht: "Nou pral bati yon apèsi sou mezi pou biznis ou, gratis, san okenn kondisyon.", it: "Creeremo un'anteprima su misura per la tua attività, gratis, senza impegno.", ar: "سننشئ معاينة مخصّصة لعملك، مجانًا، دون أي التزام.", pl: "Zbudujemy dla twojej firmy własny podgląd, za darmo, bez zobowiązań." },
  "pv.request": { en: "Request a preview", es: "Solicitar una vista previa", zh: "申请预览", yue: "申請預覽", ru: "Запросить превью", fr: "Demander un aperçu", bn: "একটি প্রিভিউ অনুরোধ করুন", ko: "미리보기 요청", ht: "Mande yon apèsi", it: "Richiedi un'anteprima", ar: "اطلب معاينة", pl: "Poproś o podgląd" },
