  "lg.updated": { en: "Last updated, June 2026", es: "Última actualización, junio de 2026", zh: "最后更新，2026 年 6 月", yue: "最後更新，2026 年 6 月", ru: "Последнее обновление, июнь 2026", fr: "Dernière mise à jour, juin 2026", bn: "সর্বশেষ হালনাগাদ, জুন ২০২৬", ko: "최종 업데이트, 2026년 6월", ht: "Dènye mizajou, jen 2026", it: "Ultimo aggiornamento, giugno 2026", ar: "آخر تحديث، يونيو 2026", pl: "Ostatnia aktualizacja, czerwiec 2026" },
